actions.scriptContent:
var old = txn.custom.approvalHistory;
// console.log(old);

var stages = {
  "draft": "Draft",
  "pendingApproval": "Pending Approval",
  "rejected": "Rejected",
  "approved": "Approved",
  "sentToCustomer": "Sent to Customer",
  "ordered": "Ordered"
};

var timestamp = Date.now().toISOString();
// console.log(timestamp);

var dateString = timestamp;
var year = dateString.substring(0, 4);
var month = dateString.substring(5, 7);
var day = dateString.substring(8, 10);
var formattedDate = month + "/" + day + "/" + year;

var stageAdder = "\n" + formattedDate + " Transitioned to ";

if (stages.has(txn.stage)){
  var sLabel = stages.get(txn.stage);
  stageAdder += sLabel + " by " + txn.modifiedBy;
}
else{
  stageAdder += txn.stage + " by " + txn.modifiedBy;
}

// Do not add to history if current stage is already added, prevents duplicate lines when a new user opens the transaction
if (old && (old.substring(11, 30) == stageAdder.substring(11, 30))) {
  return old;
}

// Only prepend if this entry isn't already the most recent entry, prevents duplicate lines when transitioning between stages
if (old && old.trim().startsWith(stageAdder.trim())) {
  return old;
}

return stageAdder + old;


